import re

from moler.exceptions import ParsingDone, CommandFailure

__author__ = 'Tomasz Krol'
__copyright__ = 'Copyright (C) 2022, Nokia'
__email__ = 'tomasz.krol@nokia.com'

from ta_moler.cmd.hub.rfswcli.generichub import GenericHub


class ConfigReset(GenericHub):
    """ConfigReset command class."""

    def build_command_string(self):
        """
        Build command string.

        :return: String representation of command to send over connection to device.
        """
        return "config_reset resetHubPasswords"

    def on_new_line(self, line, is_full_line):
        """
        Parse the output of the command.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        try:
            self._parse_password_reset_successfully(line)
            self._parse_reboot_shub(line)
            self._parse_password_error(line)
        except ParsingDone:
            pass
        return super(ConfigReset, self).on_new_line(line, is_full_line)

    # Both admin and hubapp users's password reset successfully!
    _re_password_reset_successfully = re.compile(r"Both admin and hubapp users's password reset successfully!")

    def _parse_password_reset_successfully(self, line):
        """
        Parse password reset successfully.

        :param line: Line from device.
        :return: None but raises ParsingDone if all required commands are sent.
        """
        if self._regex_helper.search_compiled(ConfigReset._re_password_reset_successfully, line):
            self.current_ret["PASSWORD_RESET"] = True

            raise ParsingDone

    # Start to reboot sHUB...
    _re_start_to_reboot = re.compile(r'Start to reboot sHUB...')

    def _parse_reboot_shub(self, line):
        """
        Parse start to reboot sHUB.

        :param line: Line from device.
        :return: None but raises ParsingDone if all required commands are sent.
        """
        if self._regex_helper.search_compiled(ConfigReset._re_start_to_reboot, line):
            self.current_ret["REBOOT_HUB"] = True

            raise ParsingDone

    # Error! St13runtime_error: BBU is online, so reject this action!
    _re_reset_error = re.compile(r"(?P<ERROR>.*ERROR.*)", re.IGNORECASE)

    def _parse_password_error(self, line):
        """
        Parse error.

        :param line: Line from device.
        :return: None but raises ParsingDone if all required commands are sent.
        """
        if self._regex_helper.search_compiled(ConfigReset._re_reset_error, line):
            self.set_exception(CommandFailure(self, f"Unexpected error: '{self._regex_helper.group('ERROR')}'"))

            raise ParsingDone


COMMAND_OUTPUT = """rfsw> config_reset resetHubPasswords
Both admin and hubapp users's password reset successfully!
Start to reboot sHUB...
rfsw> """

COMMAND_KWARGS = {
}

COMMAND_RESULT = {
    "PASSWORD_RESET": True,
    "REBOOT_HUB": True,
}
